			Part = Instance.new("WedgePart")
		elseif P[2] == 3 then
			Part = Instance.new("Seat")
		else
			Part = Instance.new("Part")
		end
		if P[2] == 1 then Part.Shape = Enum.PartType.Cylinder end
		Part.Name = P[1]
		Part.Size = Vector3.new(P[4], P[5], P[6])
		Part.CFrame = Base * CF(P, 7)
		local M = MATS[MATN[P[3] + 1]] or {Enum.Material.Plastic, Color3.new(1, 0, 1), 0}
		Part.Material, Part.Color, Part.Transparency = M[1], M[2], M[3]
		if M[4] then Part.MaterialVariant = M[4] end -- a texture-pack MaterialVariant
		Part.Anchored = true
		Part.TopSurface, Part.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
		Part.CanCollide = Collides(PF.k, P[1])
		Part.CastShadow = Part.Size.X * Part.Size.Y * Part.Size.Z > 1.5
		if P[14] == 1 then -- a region marker: invisible, no collision, queries or touches (MARKER_ACCESS below)
			Part.Transparency, Part.CanCollide, Part.CanQuery, Part.CanTouch, Part.CastShadow = 1, false, false, false, false
		end
		if type(P[15]) == "string" and P[15] ~= "" then -- "" = no attributes (export rows keep fields 14-16 together)
			for K, V in pairs(HS:JSONDecode(P[15])) do
				Part:SetAttribute(K, V)
			end
		end
		if type(P[16]) == "string" then -- "" = no tags
			for T in string.gmatch(P[16], "[^,]+") do
				T = T:match("^%s*(.-)%s*$")
				if T ~= "" then CS:AddTag(Part, T) end
			end
		end
		if P[14] == 1 then -- per-tag exceptions: only where a service needs a touch or a query
			for _, T in ipairs(CS:GetTags(Part)) do
